      await customerAccountPage.page.getByLabel("Password *").fill("this-is-a-wrong-password-xyz");
    });

    await test.step("And I click the \"login\" button", async () => {
      await customerAccountPage.page.getByRole("button", { name: "Login" }).click();
    });

